function validate([low, high]) {
  for (const s of [low, high]) {
    if (typeof s !== 'string' || s.length < 1 || s.length > 15) return 'low and high have 1 to 15 digits.';
    if (!/^[0-9]+$/.test(s)) return 'low and high contain only digits.';
    if (s.length > 1 && s[0] === '0') return 'Numbers have no leading zeros (except 0 itself).';
  }
  if (low.length > high.length || (low.length === high.length && low > high)) return 'low must not be greater than high.';
  return null;
}

