function strobogrammaticInRange(low, high) {
  const mirror = { 0: '0', 1: '1', 6: '9', 8: '8', 9: '6' };
  let count = 0;

  const inRange = (text) => {
    if (text.length === low.length && text < low) return false;
    if (text.length === high.length && text > high) return false;
    return true;
  };

  const build = (front, back, remaining) => {
    if (remaining === 0) {
      if (inRange(front + back)) count++;
      return;
    }
    if (remaining === 1) {
      for (const middle of '018') {
        build(front + middle, back, 0);
      }
      return;
    }
    for (const digit of '01689') {
      if (front === '' && digit === '0') continue;
      build(front + digit, mirror[digit] + back, remaining - 2);
    }
  };

  for (let length = low.length; length <= high.length; length++) {
    build('', '', length);
  }
  return count;
}

