function strobogrammaticInRange(low, high) {
  // Grow every strobogrammatic string from the middle outwards, one layer of two digits at a time.
  const turn = { 0: '0', 1: '1', 6: '9', 8: '8', 9: '6' };
  const lo = BigInt(low), hi = BigInt(high);
  const layers = [[''], ['0', '1', '8']];
  let total = 0;
  for (let size = 0; size <= high.length; size++) {
    if (size >= 2) {
      const next = [];
      for (const inner of layers[size - 2]) for (const d of Object.keys(turn)) next.push(d + inner + turn[d]);
      layers.push(next);
    }
    if (size === 0) continue;
    for (const s of layers[size]) {
      if (s.length > 1 && s[0] === '0') continue;
      const rotated = s.split('').reverse().map(c => turn[c]).join('');
      if (rotated !== s) continue;
      const value = BigInt(s);
      if (value >= lo && value <= hi) total++;
    }
    if (size >= 2) layers[size - 2] = null;
  }
  return total;
}

