function generate(rand, size) {
  const pairs = [['0', '0'], ['1', '1'], ['6', '9'], ['8', '8'], ['9', '6']];
  const randomNumber = (length) => {
    let s = String(1 + Math.floor(rand() * 9));
    while (s.length < length) s += Math.floor(rand() * 10);
    return s;
  };
  const strobo = (length) => {
    const digits = new Array(length);
    for (let left = 0, right = length - 1; left <= right; left++, right--) {
      const options = pairs.filter(([a, b]) => (left !== right || a === b) && (left !== 0 || length === 1 || a !== '0'));
      const [a, b] = options[Math.floor(rand() * options.length)];
      digits[left] = a;
      digits[right] = b;
    }
    return digits.join('');
  };
  const pick = (maxLength) => {
    const length = 1 + Math.floor(rand() * maxLength);
    const r = rand();
    if (r < 0.08) return '0';
    return r < 0.45 ? strobo(length) : randomNumber(length);
  };
  const less = (a, b) => a.length !== b.length ? a.length < b.length : a < b;
  let low, high;
  if (size === 'large') {
    low = pick(3);
    high = rand() < 0.5 ? strobo(15) : randomNumber(15);
  } else {
    low = pick(6);
    high = pick(6);
  }
  return less(high, low) ? [high, low] : [low, high];
}
